	/**
	 * Default Constructor
	 */
    public ContractService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ContractEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ContractRepository.class) );
		this.validator		= applicationContext.getBean(ContractValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Contract
	 */
		public Contract createContract( CreateContractCommand command ) {

		Contract entity = new Contract();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setContractId( command.getContractId() );
            entity.setContractNumber( command.getContractNumber() );
            entity.setStartDate( command.getStartDate() );
            entity.setEndDate( command.getEndDate() );
            entity.setRenewalTermMonths( command.getRenewalTermMonths() );
            entity.setAutoRenew( command.getAutoRenew() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Contract {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateContractCommand
	 * @return		Contract
	 */
	public Contract updateContract( UpdateContractCommand command ) {

		Contract entity = new Contract();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setContractId( command.getContractId() );
            entity.setContractNumber( command.getContractNumber() );
            entity.setStartDate( command.getStartDate() );
            entity.setEndDate( command.getEndDate() );
            entity.setRenewalTermMonths( command.getRenewalTermMonths() );
            entity.setAutoRenew( command.getAutoRenew() );
            entity.setOrganization( command.getOrganization() );
            entity.setAccount( command.getAccount() );
            entity.setOwner( command.getOwner() );
            entity.setOrders( command.getOrders() );
            entity.setCases( command.getCases() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Contract {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteContractCommand
	 */
	public void delete( DeleteContractCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getContractId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Contract {0} ", id );

	}

	/**
	 * Method to retrieve the Contract via ContractFetchOneSummary
	 * @param 	summary ContractFetchOneSummary
	 * @return 	ContractFetchOneResponse
	 */
	public Contract getContract( ContractFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ContractFetchOneSummary arg cannot be null" );

		Contract entity = null;
		UUID id = summary.getContractId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Contract using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Contracts
	 *
	 * @return 	List<Contract>
	 */
    public List<Contract> getAllContract() {
		List<Contract> list = projector.findAll( new FindAllContractQuery() );
		return list;
	}

	/**
	 * assign Organization on Contract
	 * @param		command AssignOrganizationToContractCommand
	 */
	public void assignOrganization( AssignOrganizationToContractCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getContractId(), command.getAssignment());

	}

